"""Copy every disbursement from the Meridian Disbursements API into disbursements.jsonl."""
import argparse
import json
import urllib.request
import urllib.parse


def fetch_disbursements(base_url):
    url_base = f"{base_url}/v2/disbursements"
    cursor = None
    seen = {}
    while True:
        params = []
        if cursor:
            params.append(f"cursor={urllib.parse.quote(cursor)}")
        params.append("limit=100")
        query = "?" + "&".join(params)
        with urllib.request.urlopen(f"{url_base}{query}", timeout=30) as resp:
            data = json.load(resp)
        disbursements = data.get("disbursements", [])
        for d in disbursements:
            if d["id"] not in seen:
                seen[d["id"]] = d
        if data.get("drained"):
            break
        cursor = data.get("cursor")
        if not cursor:
            break
    return list(seen.values())

